<div class="head"><div><h1><?= icon('chart') ?> Reports</h1><p class="muted">Monthly billing summary.</p></div><?php if ($u['role'] === 'admin'): ?><a class="btn sm" href="<?= url('reports/activity') ?>">Activity log</a><?php endif; ?></div>
<div class="cards"><div class="card-stat c-blue">Total Billed<b><?= e(money($t['billed'])) ?></b></div><div class="card-stat c-green">Collected<b><?= e(money($t['collected'])) ?></b></div><div class="card-stat c-orange">Outstanding<b><?= e(money($t['outstanding'])) ?></b></div><div class="card-stat c-purple">Collection Rate<b><?= $t['billed'] > 0 ? round($t['collected'] / $t['billed'] * 100) : 0 ?>%</b></div></div>
<div class="panel"><h2>Billing by month</h2><div class="tw"><table><tr><th>Month</th><th>Bills</th><th>Billed</th><th>Collected</th><th>Outstanding</th><th>Paid</th><th>Open</th></tr>
<?php foreach ($rows as $r): ?><tr><td><?= e($r['billing_month']) ?></td><td><?= (int)$r['n'] ?></td><td><?= e(money($r['billed'])) ?></td><td><?= e(money($r['collected'])) ?></td><td><?= e(money($r['outstanding'])) ?></td><td><?= (int)$r['paid_n'] ?></td><td><?= (int)$r['open_n'] ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="7" class="muted">No bills yet.</td></tr><?php endif; ?></table></div></div>
